def build():
    sites=json.loads((ROOT/'design/full-map-repair/sites.json').read_text(encoding='utf-8'))
    compiled=[]
    for s in sites:
        if s['id'] not in FLOORS:
            continue
        j={k:s[k] for k in ('id','room','image','rect','door','feather')}
        j['walkable']=polygon(FLOORS[s['id']])
        j['blocked']=[polygon(p) for p in BLOCKS.get(s['id'],[])]
        j['foregrounds']=[{'id':n,'depth':depth/100,'polygon':polygon(p)} for n,depth,p in FRONTS.get(s['id'],[])]
        compiled.append(j)
    (ROOT/'design/full-map-repair/geometry.json').write_text(json.dumps({'joints':compiled},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Traced joints:',len(compiled))

if __name__=='__main__':
    build()
